def rect(x,t,ww,hh,fill): c.setFillColor(C(fill));c.rect(x,H-t-hh,ww,hh,stroke=0,fill=1)
def txt(x,t,s,size=10,f='D',col=ink):c.setFillColor(C(col));c.setFont(f,size);c.drawString(x,H-t,s)
def para(y,s,x=margin,ww=width,size=10.4,leading=16,col=ink,font='D'):
    p=Paragraph(s,ParagraphStyle('p',fontName=font,fontSize=size,leading=leading,textColor=C(col),alignment=TA_LEFT));_,hh=p.wrap(ww,H);p.drawOn(c,x,H-y-hh);return y+hh

def pagehead(section,title,subtitle):
    global page
    if page:c.showPage()
    page+=1;rect(0,0,W,H,paper);txt(margin,36,'TELEDATA   /   АНАЛИТИКА УДЕРЖАНИЯ',8,'B',teal);txt(W-137,36,'ВАРИАНТ  07',8,'M',muted)
    rect(margin,46,width,1,'#B8CECA');txt(margin,80,section.upper(),9,'B',gold);txt(margin,118,title,24,'B');para(132,subtitle,size=10.5,col=muted)
    rect(margin,H-41,width,1,'#B8CECA');txt(margin,H-24,'MLOps  /  Фактический прогон 19.11.2026, UTC',8,'D',muted);txt(W-69,H-24,f'{page:02}',9,'B',teal)

def h(y,s):txt(margin,y,s,13,'B',teal)
def note(y,s):
    bar=para_height(s,width-32);rect(margin,y,width,bar+20,light);rect(margin,y,3,bar+20,teal);para(y+10,s,x=margin+15,ww=width-32,size=10,col=ink,leading=15);return y+bar+20

def para_height(s,ww):return Paragraph(s,ParagraphStyle('n',fontName='D',fontSize=10,leading=15)).wrap(ww,H)[1]
def fig(name,x,t,ww,hh):
    im=ImageReader(str(e/(name+'.png')));iw,ih=im.getSize();ratio=min(ww/iw,hh/ih);a,b=iw*ratio,ih*ratio;c.drawImage(im,x+(ww-a)/2,H-t-b,a,b,mask='auto')

def table(y,heads,rows,widths,sz=9,rh=24):
    rect(margin,y,width,rh,teal);xx=margin
    for hd,v in zip(heads,widths):txt(xx+8,y+rh*.69,hd,sz,'B','#FFFFFF');xx+=v
    y+=rh
    for i,row in enumerate(rows):
        rect(margin,y,width,rh,'#F0F4F0' if i%2==0 else '#FFFFFF');xx=margin
        for v,dw in zip(row,widths):txt(xx+8,y+rh*.68,str(v),sz);xx+=dw
        y+=rh
    return y

def label(y,t,s):h(y,t);return para(y+9,s)

